    'High': [100, 120, 110, 130, 140],
    'Low': [90, 100, 95, 110, 120],
    'Close': [100, 110, 105, 120, 130],
    'Volume': [1000, 2000, 1500, 3000, 4000]
})

kelly = volatility_trading(data)
print(kelly)
